function route(){return location.hash.replace('#/','')||'home';}
const leaveDialog=document.querySelector('#leave-dialog'),ratesDialog=document.querySelector('#rates-dialog');
let pendingNavigation=null;
function resetExchange(){state.mapContext=null;state.flowActive=false;state.request=null;state.draft={currency:'USD',toCurrency:'KRW',amount:'100',area:'haeundae',name:''};state.selected=0;state.mapArea=null;state.navigating=false;state.mapZoom=1;for(const c of Object.keys(customRates))delete customRates[c];}
function askToLeave(action){if(leaveDialog.open)return;readDraft();pendingNavigation=action;updateStatic();leaveDialog.showModal();}
function navigate(page){state.allowedRoute=page;if(route()===page){state.allowedRoute=null;render();}else location.hash='/'+page;}
function isPickupTransition(page){return Boolean(state.request)&&['code','map'].includes(page)&&['code','map'].includes(state.renderedPage);}
function go(page,options={}){if(route()===page)return;if(state.flowActive&&!options.withinFlow&&!isPickupTransition(page)){askToLeave(()=>{resetExchange();navigate(page);});return;}navigate(page);}
function progress(step,title,back='home'){return '<div class="step-head">'+(back?'<button class="back-button" data-go="'+back+'" data-flow aria-label="'+t('back')+'">'+icon('back')+'</button>':'')+'<span class="step-title">'+title+'</span><span class="step-count">0'+step+' / 04</span></div><div class="progress" aria-label="'+step+' / 4">'+[1,2,3,4].map(n=>'<span class="'+(n<step?'active':n===step?'current':'')+'"></span>').join('')+'</div>';}
function home(){return `<div class="home-heading globe-heading"><h1>${t('homeTitle')}</h1></div><section class="toy-earth" id="toy-earth" data-phase="globe"><div class="toy-stage"><button type="button" class="toy-world-button" data-earth-button aria-label="${t('toyOpen')}" aria-expanded="false"></button></div><div class="toy-caption"><p data-earth-hint>${t('toyOpen')}</p><button type="button" class="toy-replay" data-earth-replay hidden>↻ <span>${t('toyReplay')}</span></button></div><button type="button" id="start-exchange" class="toy-start"><span>${t('start')}</span><span class="toy-start-icon">${icon('chevron')}</span></button></section><div class="section-label globe-guide-heading"><h2>${t('journey')}</h2></div><div class="journey-list">${[['cash','step1','step1Desc'],['qr','step2','step2Desc'],['pin','step3','step3Desc']].map(([i,a,b])=>'<div class="journey-item"><span class="journey-icon">'+icon(i)+'</span><div><h3>'+t(a)+'</h3><p>'+t(b)+'</p></div></div>').join('')}</div><p class="home-note">${icon('shield')}<span>${t('homeNote')}</span></p>`;}
function apply(){const d=state.draft;return `${progress(1,t('apply'),false)}<div class="page-intro"><span class="eyebrow">${t('moneyTagline')}</span><h1>${t('applyTitle')}</h1><p>${t('applyDesc')}</p></div><form id="apply-form"><div class="currency-pair"><div class="form-card source-card"><label class="field-label" for="give-amount">${t('give')}<span>${t('demo')}</span></label><div class="field-controls"><div class="currency-choice"><select id="currency" class="currency-select" aria-label="${t('fromCurrency')}">${currencyOptions(d.currency)}</select><small id="source-name">${currencyName(d.currency)}</small></div><input id="give-amount" class="amount-input" type="number" inputmode="decimal" min="0.00000001" max="1000000000000" step="any" required value="${esc(d.amount)}" aria-label="${t('give')}"></div></div><button type="button" id="swap-currencies" class="swap-button" aria-label="${t('swap')}">${exchangeIcon()}</button><div class="form-card receive-card"><label class="field-label" for="receive-currency">${t('receiveCurrency')}</label><div class="field-controls"><div class="currency-choice"><select id="receive-currency" class="currency-select" aria-label="${t('toCurrency')}">${currencyOptions(d.toCurrency)}</select><small id="target-name">${currencyName(d.toCurrency)}</small></div><output class="estimate-amount" id="estimate" aria-live="polite"></output></div><div class="estimate-bottom"><span>${t('sampleRate')}</span><span id="rate-text" class="rate-text"></span></div></div></div><div id="custom-rates" class="custom-rates" hidden></div><p class="form-error" id="amount-error" hidden></p><p class="form-explainer">${t('applyNote')}<br><br>${t('quoteNote')}<br>${t('demoSupport')}</p><div class="apply-fixed-actions"><button type="button" class="fixed-rates-button" id="open-rates">${icon('clock')}<span>${t('liveRates')}</span></button><button class="button gold" type="submit">${t('submit')}${icon('chevron')}</button></div></form>`;}
