function ratesPanel(){
 const {data,error,loading}=liveRateState;
 if(loading)return '<div class="rate-loading" role="status"><span class="rate-spinner"></span>'+t('rateLoading')+'</div>';
 if(error)return '<div class="rate-error" role="alert"><p>'+t(error==='KEY_NOT_CONFIGURED'?'rateKeyMissing':error==='NO_DATA'?'rateEmpty':'rateFailure')+'</p><button class="button gold" id="retry-rates">'+t('rateRetry')+'</button></div>';
 if(!data)return '';
 const priority=['USD','JPY','CNY','CNH','TWD','EUR'];
 const rows=[...priority.filter(c=>c!=='CNY'||data.rates.some(r=>r.currency===c)).map(c=>data.rates.find(r=>r.currency===c)||{currency:c}),...data.rates.filter(r=>!priority.includes(r.currency)&&r.currency!=='KRW')];
 return '<div class="live-rates-content"><p>'+t('rateSource')+'</p><div class="rate-date"><span>'+t('rateDate')+'</span><strong>'+esc(data.rateDate)+'</strong></div><table><thead><tr><th>'+t('ratePairLabel')+'</th><th>KRW</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+(r.currency==='CNH'?t('rateYuan'):esc(currencyCountry(r.currency))+' · '+esc(r.currency))+'</strong><small>'+(r.rate?number(r.unit)+' '+esc(r.currency)+' → KRW':'')+'</small></td><td>'+(r.rate?Number(r.rate).toLocaleString(language,{minimumFractionDigits:2,maximumFractionDigits:4}):t('rateUnsupported'))+'</td></tr>').join('')+'</tbody></table><div class="live-update"><span>'+t('rateUpdated')+'</span><span>'+esc(new Date(data.fetchedAt).toLocaleTimeString(language,{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'}))+' KST</span></div><p>'+t('rateNotice')+'</p><button type="button" class="button quiet" id="retry-rates">'+t('rateRetry')+'</button></div>';
}
function drawRates(){document.querySelector('#rates-content').innerHTML=ratesPanel();document.querySelector('#retry-rates')?.addEventListener('click',loadLiveRates);}
async function loadLiveRates(){
 if(liveRateState.loading)return;
 liveRateState.loading=true;liveRateState.error=null;drawRates();
 try{
  const response=await fetch('/api/rates',{headers:{Accept:'application/json'},signal:AbortSignal.timeout(22000)});
  const data=await response.json();
  if(!response.ok)throw new Error(data.error||'RATES_UNAVAILABLE');
  if(!Array.isArray(data.rates)||!data.rateDate||!data.fetchedAt)throw new Error('RATES_UNAVAILABLE');
  liveRateState.data=data;
 }catch(error){liveRateState.data=null;liveRateState.error=error.message;}
 finally{liveRateState.loading=false;drawRates();}
}
function loading(){return `<section class="loading-screen" aria-busy="true"><span class="eyebrow">${t('preparingTagline')}</span><div class="paper-stage"><canvas id="paper-loader" aria-hidden="true"></canvas></div><h1>${t('loadingTitle')}</h1><p>${t('loadingDesc')}</p><div class="loading-track paper-track" aria-hidden="true"><span id="paper-progress"></span></div><div class="loading-status" id="loading-status" role="status">${t(state.loadingTarget==='apply'?'loading1':'loading2')}</div><span class="loading-small">${t('loadingDemo')}</span></section>`;}
function missing(){return `<div class="page-intro"><h1>${t('missing')}</h1><p>${t('homeNote')}</p></div><button class="button gold" data-go="apply">${t('start')}</button>`;}
function code(){return state.request?mapPage():missing();}
function placeName(){const area=state.mapArea||state.request?.area||state.draft.area;return region(area)+' '+t('partnerAtm')+' '+String(state.selected+1).padStart(2,'0');}
function mapPage(){return '<section id="real-atm-map" class="real-atm-map"></section>';}
function done(){return `${progress(4,t('doneStep'))}<div class="done-intro"><div class="success-art">${icon('check')}</div><span class="eyebrow">ENJOY YOUR NEXT MOMENT.</span><h1>${t('doneTitle')}</h1><p>${t('doneDesc')}</p><span class="demo-tag">${t('demo')}</span></div><div class="privacy-card">${icon('shield')}<div><h3>${t('clearedTitle')}</h3><p>${t('clearedDesc')}</p></div></div><div class="next-card">${icon('cash')}<div><h3>${t('again')}</h3><p>${t('step3Desc')}</p></div></div><p class="home-note">${t('doneDemo')}</p><div class="done-actions"><button class="button gold" data-go="apply">${t('again')}${icon('chevron')}</button><button class="button quiet" data-go="map">${t('findAtm')}</button></div>`;}
function updateStatic(){document.querySelector('.bottom-nav').setAttribute('aria-label',t('navLabel'));document.querySelector('.language-heading').textContent=t('language');document.querySelector('#language-menu').setAttribute('aria-label',t('language'));document.documentElement.lang=language;document.querySelectorAll('[data-t]').forEach(el=>el.innerHTML=t(el.dataset.t));document.querySelector('.language-toggle').setAttribute('aria-label',t('language'));document.querySelectorAll('.close-drawer,.close-route').forEach(el=>el.setAttribute('aria-label',t('close')));document.querySelector('.brand').setAttribute('aria-label','QR '+t('exchange'));document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.lang===language)));document.querySelector('#more-button').setAttribute('aria-label',t('more'));document.querySelector('#close-rates').setAttribute('aria-label',t('close'));document.title=`QR ${t('exchange')} · Busan`;}
function clearTimers(){state.mapStop?.();state.mapStop=null;state.earthStop?.();state.earthStop=null;state.paperStop?.();state.paperStop=null;state.loadingTimers.forEach(clearTimeout);state.loadingTimers=[];clearInterval(state.codeInterval);state.codeInterval=null;}
function render(options={}){clearTimers();updateStatic();const page=route();const screens={home,exchange:home,apply,loading,code,map:mapPage,done};state.renderedPage=page;if(page==='apply')state.flowActive=true;screen.innerHTML=(screens[page]||home)();document.querySelector('.phone-app').classList.toggle('map-mode',page==='map'||(page==='code'&&Boolean(state.request)));document.querySelector('.phone-app').classList.toggle('apply-mode',page==='apply');if(page==='map'||(page==='code'&&state.request))wireMap();document.querySelectorAll('[data-tab]').forEach(a=>{const active=(page==='home'||page==='exchange'?'home':page==='map'?'map':'exchange')===a.dataset.tab;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go,{withinFlow:b.hasAttribute('data-flow')})));screen.querySelector('#start-exchange')?.addEventListener('click',()=>beginLoading('apply'));screen.querySelector('#reissue')?.addEventListener('click',()=>beginLoading('code'));screen.querySelector('#copy-code')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.request.code);toast(t('copied'));}catch{toast(t('copyFail'));}});screen.querySelectorAll('[data-place]').forEach(b=>b.addEventListener('click',()=>{const scroll=window.scrollY;state.selected=Number(b.dataset.place);state.navigating=false;render({preserveScroll:true});window.scrollTo(0,scroll);}));screen.querySelector('#directions')?.addEventListener('click',()=>{state.navigating=true;render({preserveScroll:true});});screen.querySelector('#collected')?.addEventListener('click',()=>{resetExchange();go('done',{withinFlow:true});});if(page==='home'||page==='exchange')wireToyHome();if(page==='apply')wireForm();if(page==='loading')startLoading();if(page==='code'&&state.request){updateCountdown();state.codeInterval=setInterval(updateCountdown,1000);}if(!options.preserveScroll){window.scrollTo({top:0,behavior:'instant'});screen.focus({preventScroll:true});}}
function wireForm(){const form=document.querySelector('#apply-form');form.addEventListener('input',e=>{readDraft();if(e.target.matches('[data-custom-rate]'))customRates[e.target.dataset.customRate]=Number(e.target.value);updateEstimate();});form.addEventListener('change',e=>{readDraft();if(e.target.matches('#currency,#receive-currency'))renderRateInputs();updateEstimate();});document.querySelector('#swap-currencies').addEventListener('click',()=>{readDraft();const d=state.draft;const pair=ratePair();const next=pair?Number(d.amount)*pair:null;[d.currency,d.toCurrency]=[d.toCurrency,d.currency];if(next!==null&&Number.isFinite(next)&&next>0)d.amount=String(Number(next.toPrecision(12)));const y=scrollY;render({preserveScroll:true});window.scrollTo(0,y);document.querySelector('#swap-currencies').classList.add('just-swapped');});form.addEventListener('submit',e=>{e.preventDefault();readDraft();const n=Number(state.draft.amount),pair=ratePair();if(!Number.isFinite(n)||n<=0||n>1e12||!pair){const error=document.querySelector('#amount-error');error.textContent=!pair?t('rateMissing'):t('amountError');error.hidden=false;return;}state.request={currency:state.draft.currency,toCurrency:state.draft.toCurrency,amount:n,area:state.draft.area,received:Number((n*pair).toFixed(2)),won:Math.round(n*pair),code:'482917',expires:0};state.selected=0;state.mapArea=state.request.area;state.navigating=false;state.mapZoom=1;beginLoading('code');});document.querySelector('#open-rates').addEventListener('click',()=>{readDraft();ratesDialog.showModal();loadLiveRates();});renderRateInputs();updateEstimate();}
function renderRateInputs(){const area=document.querySelector('#custom-rates');const missing=state.draft.currency===state.draft.toCurrency?[]:[...new Set([state.draft.currency,state.draft.toCurrency])].filter(c=>!(c in rates));area.hidden=missing.length===0;area.innerHTML=missing.length?'<h3>'+t('customRate')+'</h3><p>'+t('rateHelp')+'</p>'+missing.map(c=>'<label>'+c+' · '+t('rateBase')+'<input type="number" inputmode="decimal" min="0.000001" step="any" data-custom-rate="'+c+'" value="'+(customRates[c]||'')+'" placeholder="1 '+c+' = ? KRW"></label>').join(''):'';}
function readDraft(){if(!document.querySelector('#apply-form'))return;state.draft.currency=document.querySelector('#currency').value;state.draft.toCurrency=document.querySelector('#receive-currency').value;state.draft.amount=document.querySelector('#give-amount').value;}
function updateEstimate(){const d=state.draft,a=Number(d.amount),pair=ratePair(),valid=d.amount!==''&&Number.isFinite(a)&&a>0&&a<=1e12;document.querySelector('#estimate').textContent=valid&&pair?formatMoney(a*pair,d.toCurrency):'—';document.querySelector('#rate-text').textContent=pair?'1 '+d.currency+' = '+Number(pair.toPrecision(6)).toLocaleString(language,{maximumFractionDigits:6})+' '+d.toCurrency:t('rateMissing');document.querySelector('#source-name').textContent=currencyName(d.currency);document.querySelector('#target-name').textContent=currencyName(d.toCurrency);document.querySelector('#amount-error').hidden=true;}
function beginLoading(target){state.flowActive=true;state.loadingTarget=target;go('loading',{withinFlow:true});}
function startLoading(){const target=state.loadingTarget;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const duration=reduced?450:7200;state.paperStop=window.startPaperLoader(document.querySelector('#paper-loader'),{duration,reducedMotion:reduced});document.querySelector('#paper-progress').style.setProperty('--count-duration',duration+'ms');if(target==='code')state.loadingTimers.push(setTimeout(()=>{const label=document.querySelector('#loading-status');if(label)label.textContent=t('loading3');},Math.floor(duration*.5)));state.loadingTimers.push(setTimeout(()=>{if(target==='code'&&state.request){state.request.expires=Date.now()+600000;}go(target==='code'&&!state.request?'apply':target,{withinFlow:true});},duration));}
function updateCountdown(){const el=document.querySelector('#code-time');if(!el||!state.request)return;const left=Math.max(0,Math.ceil((state.request.expires-Date.now())/1000));el.textContent=left?`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`:t('expired');}

function wireMap(){state.mapStop=window.AtmMap.attach({root:document.querySelector('#real-atm-map'),language,area:state.mapArea||'haeundae',labels:Object.fromEntries(Object.keys(regions).map(k=>[k,region(k)])),request:state.request,context:state.mapContext,onContextChange:context=>{state.mapContext=context;state.mapArea=context.area;},onCopy:async()=>{try{await navigator.clipboard.writeText(state.request.code);toast(t('copied'));}catch{toast(t('copyFail'));}}});}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('visible'),2800);}
const langToggle=document.querySelector('.language-toggle'),langMenu=document.querySelector('.language-menu');
function closeLanguages(focus=false){langMenu.hidden=true;langToggle.setAttribute('aria-expanded','false');if(focus)langToggle.focus();}
function openLanguages(focus=false){langMenu.hidden=false;langToggle.setAttribute('aria-expanded','true');if(focus)langMenu.querySelector('[aria-selected="true"]').focus();}
langToggle.addEventListener('click',()=>langMenu.hidden?openLanguages():closeLanguages());langToggle.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();openLanguages(true);}});
langMenu.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{readDraft();language=b.dataset.lang;try{localStorage.setItem('qr-exchange-language',language);}catch{}render({preserveScroll:true});closeLanguages(true);}));
langMenu.addEventListener('keydown',e=>{const buttons=[...langMenu.querySelectorAll('[data-lang]')];const i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}if(e.key==='Escape'){e.preventDefault();closeLanguages(true);}});
document.addEventListener('click',e=>{if(!e.target.closest('.language'))closeLanguages();});document.addEventListener('focusin',e=>{if(!e.target.closest('.language'))closeLanguages();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLanguages();});
const moreButton=document.querySelector('#more-button');moreButton.addEventListener('click',()=>{closeLanguages();drawer.showModal();moreButton.setAttribute('aria-expanded','true');});document.querySelector('.close-drawer').addEventListener('click',()=>drawer.close());drawer.addEventListener('close',()=>{moreButton.setAttribute('aria-expanded','false');moreButton.focus();});drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)drawer.close();}});document.querySelector('#login-open').addEventListener('click',()=>{const p=document.querySelector('#login-preview');p.hidden=!p.hidden;});document.querySelectorAll('[data-provider]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#login-message').textContent=b.dataset.provider+' · '+t('loginDemo');}));document.querySelectorAll('.close-route').forEach(b=>b.addEventListener('click',()=>routeDialog.close()));
document.querySelector('#stay-exchange').addEventListener('click',()=>{pendingNavigation=null;leaveDialog.close();});
document.querySelector('#discard-exchange').addEventListener('click',()=>{const action=pendingNavigation;pendingNavigation=null;leaveDialog.close();action?.();});
leaveDialog.addEventListener('cancel',()=>{pendingNavigation=null;});
document.querySelector('#close-rates').addEventListener('click',()=>ratesDialog.close());
document.querySelectorAll('a[href^="#/"]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();go(a.getAttribute('href').slice(2));}));
window.addEventListener('beforeunload',e=>{if(state.flowActive){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const next=route();if(state.allowedRoute===next)state.allowedRoute=null;else if(state.flowActive&&state.renderedPage&&next!==state.renderedPage&&!isPickupTransition(next)){const previous=state.renderedPage;history.replaceState(null,'','#/'+previous);askToLeave(()=>{resetExchange();navigate(next);});return;}if(drawer.open)drawer.close();if(routeDialog.open)routeDialog.close();if(ratesDialog.open)ratesDialog.close();closeLanguages();render();});window.addEventListener('pagehide',()=>{clearTimers();state.request=null;state.draft.name='';});
if(!location.hash||!['home','exchange','apply','loading','code','map','done'].includes(route()))history.replaceState(null,'','#/home');render();

function wireToyHome(){const root=document.querySelector('#toy-earth');if(!root||!window.PlayfulEarth)return;state.earthStop=window.PlayfulEarth.attach({root,expanded:Boolean(state.toyExpanded),onExpand:()=>{state.toyExpanded=true;},onStart:()=>beginLoading('apply'),strings:{open:t('toyOpen'),ready:t('toyReady'),opening:t('toyOpening')}});}
